// Example using AWS SDK for Java v2 to query DynamoDB, respecting partition and sort keys
public List<UserEvent> fetchUserEvents(DynamoDbClient ddb, String userId, Instant startTime) {
    String tableName = "UserEvents";

    Map<String, AttributeValue> expressionValues = new HashMap<>();
    expressionValues.put(":uid", AttributeValue.builder().s(userId).build());
    expressionValues.put(":stime", AttributeValue.builder().s(startTime.toString()).build());

    QueryRequest queryRequest = QueryRequest.builder()
        .tableName(tableName)
        .keyConditionExpression("userId = :uid AND eventTimestamp >= :stime")
        .expressionAttributeValues(expressionValues)
        .consistentRead(false)
        .build();

    QueryResponse response = ddb.query(queryRequest);
    return response.items().stream()
        .map(UserEvent::fromItem)
        .collect(Collectors.toList());
}
